import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BQq6mqvm.js";const u=JSON.parse('{"title":"个人设置","description":"","frontmatter":{},"headers":[],"relativePath":"usage/profile.md","filePath":"usage/profile.md","lastUpdated":1790385461000}'),o={name:"usage/profile.md"};function l(i,t,s,n,h,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="个人设置" tabindex="-1">个人设置 <a class="header-anchor" href="#个人设置" aria-label="Permalink to &quot;个人设置&quot;">​</a></h1><p>点击右上角的姓名 → <strong>个人设置</strong>。</p><h2 id="查看账号信息" tabindex="-1">查看账号信息 <a class="header-anchor" href="#查看账号信息" aria-label="Permalink to &quot;查看账号信息&quot;">​</a></h2><p>页面顶部显示你的账号信息：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>姓名</td><td>显示名称，可以重名</td></tr><tr><td>工号</td><td>登录用，由管理员设定，不可修改</td></tr><tr><td>角色</td><td>普通用户 / 管理员</td></tr><tr><td>账号状态</td><td>正常 / 已停用</td></tr><tr><td>我的目录</td><td>你的文件存放位置</td></tr><tr><td>我的用量</td><td>你上传了多少个文件、占多少空间</td></tr><tr><td>最后登录</td><td>上次登录的时间</td></tr><tr><td>创建时间</td><td>账号创建时间</td></tr></tbody></table><h2 id="修改密码" tabindex="-1">修改密码 <a class="header-anchor" href="#修改密码" aria-label="Permalink to &quot;修改密码&quot;">​</a></h2><p>在「修改密码」区域：</p><ol><li>输入<strong>当前密码</strong></li><li>输入<strong>新密码</strong>（至少 6 位）</li><li>再输入一次<strong>确认</strong></li><li>点击「保存并重新登录」</li></ol><p>修改成功后会跳回登录页，需要用新密码登录。</p><div class="warning custom-block"><p class="custom-block-title">所有设备都会退出</p><p>修改密码后，你之前在其它电脑或手机上登录的会话会<strong>立即失效</strong>，需要重新登录。</p></div><h2 id="忘记密码" tabindex="-1">忘记密码 <a class="header-anchor" href="#忘记密码" aria-label="Permalink to &quot;忘记密码&quot;">​</a></h2><p>系统不支持自助找回，请联系管理员在<strong>用户管理</strong>里重置。</p><h2 id="关于我的目录" tabindex="-1">关于我的目录 <a class="header-anchor" href="#关于我的目录" aria-label="Permalink to &quot;关于我的目录&quot;">​</a></h2><p>每位成员都有一个独立目录，你的文件都放在里面。</p><p>其他人可以<strong>浏览和下载</strong>你目录里的文件，但<strong>不能修改或删除</strong>。同样，你也不能修改别人的文件。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./files">浏览与下载</a></li><li><a href="./../guide/faq">常见问题</a></li></ul>',17)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
